  // --- more passkeys, one-time codes for another device (#95) ---
  '1 passkey': '1 个通行密钥',
  'A one-time code lets your phone or another computer sign in with a passkey of its own.': '一次性代码可让你的手机或其他电脑用自己的通行密钥登录。',
  'Add a passkey': '添加通行密钥',
  'Add another device': '添加其他设备',
