  'Code from your other device': '来自你另一台设备的代码',
  'Confirm with a passkey': '用通行密钥确认',
  'Confirmed. Now create the new passkey; your browser will ask where to keep it.': '已确认。现在创建新的通行密钥，浏览器会问你要把它存在哪里。',
  'Copy link': '复制链接',
  'Create a passkey on this device for the profile “{0}”. It signs you in here from now on.': '在此设备上为档案“{0}”创建通行密钥。从现在起，你在这里用它登录。',
  'Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.': '每个通行密钥都能从保存它的设备或密码管理器登录此档案。点按一个即可重命名或移除。',
  'Enter the code from your other device.': '输入你另一台设备上的代码。',
  'For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.': '用于此设备、安全密钥、密码管理器，或通过浏览器自带的二维码使用你的手机。请先确认是你本人。',
  'It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.': '它将无法再登录此档案。已用它登录的设备会保持登录。如果设备丢失，请使用“在所有设备上退出登录”。',
  'It is your only way in, so it cannot be removed until there is another.': '这是你唯一的登录方式，在有其他方式之前不能移除。',
