  '{0} sets bring an {1} with them. Switch on Effort per set in Settings to see it.': '{0} 组自带 {1}。在设置中打开“每组强度”就能看到。',
  '{0} sets bring an {1} with them.': '{0} 组自带 {1}。',
  'RIR': 'RIR',
  'RPE': 'RPE',
  'Effort per set': '每组强度',
  'What are RIR and RPE?': 'RIR 和 RPE 是什么？',
  'How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.': '记录这一组有多吃力，就写在重量和次数旁边。同一个判断的两种标度，只是从相反的一端开始数。',
  'How it felt': '感受',
  'Nothing left, went to failure': '一点不剩，做到力竭',
  'One more rep in the tank': '还能再做一次',
  'Two more reps': '还能再做两次',
  'Three more reps': '还能再做三次',
  'Easy, warm-up territory': '轻松，热身区间',
  'Maybe half a rep left': '也许还能再做半次',
  'How hard was that set?': '这组有多吃力？',
  'Tap how many reps you had left, or type an exact {0}.': '点选你还能再做几次，或直接输入准确的 {0}。',
  'Exact {0}': '准确的 {0}',
  'Clear rating': '清除评分',
  'RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.': 'RIR 数的是你还留了几次；RPE 把同样的吃力程度放到 10 分制里来读，所以 RPE ≈ 10 − RIR。选你习惯的那种就行。',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.': '高亮那一行是大多数正式组落在的位置。已经记录的组保留原来的标度，而且别的地方不会读取这个值，所以进阶和预估 1RM 都不受影响。',
  // --- effort in the stats ---
