  'Where the sets land': '组都落在哪里',
  'Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.': '大多数正式组应该接近力竭，而不是真的力竭。一半在最底、一半在最顶，平均下来照样看着很健康。',
  'Average effort per workout': '每次训练的平均强度',
  'A fuller dot means less left in the tank. The same weight at a lower {0} is progress the line alone doesn’t show.': '点越实，说明油箱里剩得越少。同样的重量配上更低的 {0}，是光看曲线看不出来的进步。',

