  'Your server has no Coach enabled. Ask its admin, or bring your own key below.': '你的服务器没有启用教练。请联系管理员，或在下方使用你自己的密钥。',
  'Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.': '你的服务器使用管理员设置的提供商运行教练。除了已同步的内容外，此手机不会发送任何新数据。',
