  'Your server no longer accepts this browser. Your changes are kept here.': '你的服务器不再接受此浏览器。你的更改保留在这里。',
  'This phone is no longer paired with your server. Your changes are kept here.': '这部手机已不再与你的服务器配对。你的更改保留在这里。',
