  'Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': '请重试，或先导出备份。如果仍然继续，这些更改的副本会保留在此设备上，直到它再次以此账号连接到此服务器。届时会重新加入。',
  'Syncing…': '正在同步…',
  'Try again': '重试',
  'Last synced: {0}': '上次同步：{0}',
  'Not synced with this server yet': '尚未与此服务器同步',
  'Server & sync': '服务器与同步',
  'Signed in as {0}': '已登录为 {0}',
  'Sync now': '立即同步',
  'Your changes are kept here, and merged into your account once it is paired again.': '你的更改保留在这里，重新配对后会合并到你的账号。',
  'Your changes are kept here, and merged into your account once you are signed in again.': '你的更改保留在这里，重新登录后会合并到你的账号。',
  'Changes kept for {0}': '为 {0} 保留的更改',
  'Added back when this device connects as that account again.': '此设备再次以该账号连接时会重新加入。',
  'The changes your server has not seen are kept on this device, and added back when it connects as this account again.': '服务器尚未收到的更改会保留在此设备上，并在它再次以此账号连接时重新加入。',
  'This phone switches back to local-only and its copy of your account is removed. First it checks that your server has every change. If not, you choose what happens to them.': '这部手机将切换回仅本地模式，并删除其中的账号副本。会先检查你的服务器是否已有全部更改。如果没有，由你决定如何处理。',
  'Your data is removed from this browser; your profile on the server keeps it. First it checks that the server has every change. If not, you choose what happens to them.': '你的数据将从此浏览器中删除；服务器上的个人资料会保留它们。会先检查服务器是否已有全部更改。如果没有，由你决定如何处理。',
  'Signs this profile out on every device, including this one. Phones paired with it are disconnected and have to be paired again. Your passkeys keep working, so you can sign in with them again anytime.': '在所有设备（包括此设备）上退出此个人资料。与它配对的手机会断开连接，需要重新配对。你的通行密钥仍然有效，随时可以用它们重新登录。',
  '{0} change': '{0} 项更改',
  '{0} changes': '{0} 项更改',
  // --- plan vs session: the routine's own reps, per-routine progress (#275, #216) ---
  'Default progression': '默认进阶方式',
  'Planned sessions start from': '计划训练的起点',
  'The routine’s sets and reps. Your history decides the weight.': '按训练日的组数和次数，重量由你的历史记录决定。',
  'Your last session': '你的上次训练',
  'The reps you logged last time in that routine, carried over, and any warm-ups you set up yourself. With progression off, the weight too.': '沿用你上次在该训练日记录的次数，以及你自己设置的热身组。关闭进阶时，重量也一并沿用。',
  'Last time means': '“上次”指的是',
  'This routine': '这个训练日',
  'Your last session of the exercise in the same routine. Heavy day and light day stay apart.': '同一个训练日里这个动作的上一次。重训日和轻训日互不干扰。',
  'Any workout': '任意训练',
  'The last time you did the exercise, whichever routine it was in.': '你上一次做这个动作的时候，不管是哪个训练日。',
  'Plan changed, so starting from your new target.': '计划已更改，所以从你的新目标开始。',
  'First time in this routine, so starting from its own target.': '第一次练这个训练日，所以从它自己的目标开始。',
  'No weight logged last time. Enter what you lift and progression takes it from there.': '上次没有记录重量。填上你实际举的重量，进阶就从那里接手。',
  'Plan: {0}': '计划：{0}',
