  'reps from your last session': '次数沿用上次训练',
  'Save as routine?': '要保存为训练计划吗？',
  'Save as routine': '保存为训练计划',
  'Create an independent routine from these exercise targets. Your workout history is kept.': '根据这些训练目标创建独立训练计划。你的训练记录会保留。',
  'Pause': '暂停',
  'Keep timing after target': '达到目标后继续计时',
  'Timed sets continue up to 15 extra minutes. Tap Done to log the actual duration.': '计时组最多继续 15 分钟。点击“完成”记录实际时长。',
  'Edit workout': '编辑训练',
  'Workout updated': '训练已更新',
  'Save workout changes?': '保存训练更改？',
  'Save your edits to this workout, or keep the original record.': '保存对此训练的编辑，或保留原始记录。',
  'Save changes': '保存更改',
  "Don't save": '不保存',
  'Keep editing': '继续编辑',
  'This workout was deleted on another device. Your edits are still here.': '此训练已在另一台设备上删除。你的编辑仍保留在这里。',
  'Close editor': '关闭编辑器',
  'Editing a saved workout. Date and duration stay unchanged.': '正在编辑已保存的训练。日期和时长保持不变。',
  // --- demo build (v1.3.7) ---
  'A pull for every press, so the shoulders stay balanced.': '每个推的动作都配一个拉的动作，让肩部保持平衡。',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': '根据你列出的器械，安排为每周三次训练、两天轮换。先做复合动作，每个推配一个拉，并让两天之间有足够的重叠，确保任何部位都不会两周得不到训练。',
  'Based on the training already in this demo profile.': '基于此演示档案中已有的训练。',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': '目标是增重，但体重已经四周没动了。这是厨房的问题，不是训练的问题。拖后腿的不是计划。',
  'Demo': '演示',
  'Demo data reset': '演示数据已重置',
  'Direct arm work, since you asked for it.': '直接的手臂训练，因为你要求了。',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': '这个动作的主要组连续三次训练都在 RPE 9.5 或以上，而重量没有变化。把动作换掉四周，通常比死磕同一个动作更快突破平台期。',
  'Example data, stored only in this browser. Go wild and change anything you like.': '示例数据，只保存在此浏览器中。放开玩，想改什么就改什么。',
  'Full body A': '全身 A',
  'Full body B': '全身 B',
  'Horizontal pressing, the other half of the session.': '水平推，训练的另一半。',
  'Live demo. Everything stays in this browser.': '在线演示。所有内容都留在此浏览器中。',
  'No training history yet, so starting conservatively.': '还没有训练记录，所以先保守开始。',
  'Passkey sign-in, sync across your devices, your own data.': '通行密钥登录、多设备同步、数据归你所有。',
  'Puts the example plan, workouts and weigh-ins back the way they started.': '将示例计划、训练和体重记录恢复到最初的样子。',
  'Reset': '重置',
  'Reset demo data': '重置演示数据',
  'Reset demo data?': '重置演示数据？',
  'Revised as you asked. Everything you did not question is exactly as it was.': '已按你的要求修改。你没有提出疑问的部分完全保持原样。',
  'Same pattern, higher reps than day A.': '相同的动作模式，次数比 A 日更多。',
  'Self-host it in a minute →': '一分钟内自托管 →',
  'Self-host openGym': '自托管 openGym',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': '训练时间大约超出了十五分钟。这个辅助动作少做一组损失最小。',
  'Start the demo': '开始演示',
  'The main lower-body driver, where most of the strength comes from.': '下肢的主力动作，大部分力量都来自这里。',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': '相同的模式，不同的变式：重叠得够多才能进步，差异够大才能保持新鲜。',
  'The two big lower-body and pressing patterns first, while you are fresh.': '趁体力充沛时，先做下肢和推这两个大模式。',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.': '此演示完全在你的浏览器中用示例数据运行，不会发送任何内容。通行密钥登录和多设备同步随 openGym 服务器提供，自托管即可获得。',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': '有三处值得调整，还有一件值得知道。其他一切都很好：深蹲和拉的动作都在按计划进步。',
  'Vertical pressing.': '垂直推。',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': '你已经连续三周把这次训练挪到周六了。与其每次都手动改，不如直接写进计划。',
