  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": "今天的训练在这里。点一下就开练。休息日就写休息日，不用内疚。",
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": "在固定的星期几训练，或让训练计划轮换循环，下一个会等着你。",
