  // --- Settings → Integrations (1.4.4) ---
  "This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.": "这个在手机上的 openGym 应用里：iPhone 用 Apple Health，Android 用 Health Connect。",
  "Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.": "Webhook 由你自己的 openGym 服务器发送，所以需要一台服务器。在“账户”里把这台设备连上去。",
  "Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.": "这台服务器关闭了 Webhook。在它的 .env 里加上 INTEGRATIONS=webhook，然后重启。",
  "The MCP server runs next to your own openGym server and reads your data there.": "MCP 服务器运行在你的 openGym 服务器旁边，并在那里读取你的数据。",
  "Only what you switch on talks to anything. The rest stays out of your way.": "只有你打开的才会和外部通信，其他的不会打扰你。",
  "Could not reach your server": "连不上你的服务器",
  "Tap to try again": "点按重试",
  "Disconnect {0}?": "断开 {0}？",
  "openGym stops writing and reading. What it already wrote can stay there as your data, or go.": "openGym 将停止写入和读取。已经写入的内容可以作为你的数据保留，也可以删除。",
  "Works with": "兼容",
