  "Tell Home Assistant, n8n or ntfy when you finish a workout.": "训练结束时通知 Home Assistant、n8n 或 ntfy。",
  "A signed JSON message when a workout is finished, a record falls or you weigh in.": "训练结束、破纪录或称重时，发送一条签名的 JSON 消息。",
  "Sent by your server, from whichever device you logged on.": "由你的服务器发送，不管你在哪台设备上记录。",
  "Plans and reviews from the model you pick.": "由你选择的模型给出计划和回顾。",
