  "NFC sticker for this exercise": "这个动作的 NFC 贴纸",
  "Put it on your locker, your bag or the gym door. One tap with your phone and you’re in.": "贴在储物柜、包或健身房门上。手机一碰就搞定。",
  "Set up an NFC sticker": "设置 NFC 贴纸",
