  "Stick it on the machine. Tap it during a workout to jump to {0}, or to add it.": "贴在器械上。训练时碰一下就跳到{0}，或把它加进来。",
  "Sticker ready.": "贴纸已就绪。",
  "Sticker ready. Tap it with your phone to try it.": "贴纸已就绪。用手机碰一下试试。",
  "Tap it at the gym to start your workout or show your code.": "在健身房碰一下，开始训练或显示你的会员码。",
  "That didn’t work. Hold your phone still on the sticker and try again.": "没成功。把手机稳稳贴在贴纸上再试一次。",
  "This sticker can’t hold a link. Try an NTAG sticker.": "这张贴纸存不下链接。试试 NTAG 贴纸。",
  "This sticker is for an exercise you don’t have.": "这张贴纸对应的动作你没有。",
