  // --- Your year in openGym (lib/wrapped-cards.js, components/Wrapped.jsx) ---
  "Mostly in the morning. The early bird gets the barbell.": "大多在早上练。早起的鸟儿有杠铃举。",
  "Mostly around lunch. Who needs a lunch break anyway?": "大多在午饭前后练。午休是什么，能吃吗？",
  "Mostly in the afternoon. The sweet spot.": "大多在下午练。黄金时段。",
  "Mostly in the evening. Work, then work out.": "大多在晚上练。先上班，再上强度。",
  "Mostly late at night. The gym is all yours.": "大多在深夜练。整个健身房都是你的。",
  "Early bird": "早起鸟",
  "Most of your sessions started before 9. The sun was still catching up.": "你大部分训练都在 9 点前开始。太阳还在赶来的路上。",
