  "Straight into the work sets.": "直接进入正式组。",
  "That workout is over, so these can’t be applied any more.": "那次训练已结束，这些无法再应用。",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "应用从你的工作重量往上排热身：重的多几组，轻的少几组，按你健身房的杠铃片。",
