  "There’s no workout running.": "没有进行中的训练。",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "这些热身每次都在正式组之前，按工作重量的比例，所以会跟着一起涨。",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "这是演示版，后面没有 AI 模型。在你自己的服务器上，我会读你的训练并给出这样的建议。",
