  "The sharing text changed. Have a quick read and try again.": "分享说明有更新。快速看一遍再试一次。",
  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "这对这个服务器上的所有人公开：在这里有账户的每个人都能查看、试用和复制。你的名字和日期会始终随之显示。只分享属于你的东西：你自己做的、录的，或者你有权转给别人的。内置动作库中的动作图片和动画受许可保护，永远不能分享。你可以随时停止分享；别人已经领取的副本会留在他们那里。",
