  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "{0} 放行了你，但此服务器只接受特定群组。请让服务器管理者把你加进去。",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "{0} 返回了我们无法验证的内容，所以没有人登录。如果反复出现，管理页面会显示原因。",
