  "Body composition from your scale": "来自体重秤的身体成分",
  "Body fat and lean mass, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "体脂率和瘦体重，按体重秤保存的样子显示。在身体围度下查看，绝不会混进你自己记录的数据。",
  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "体脂率、瘦体重、骨量、体内水分和基础代谢率，按体重秤保存的样子显示。在身体围度下查看，绝不会混进你自己记录的数据。",
