  "Cardio goes up as what it was: a run, a ride, a row. Strength as Weight Training, with every set in the description.": "有氧按原样上传：跑步、骑行、划船。力量训练作为重量训练上传，每一组都写在描述里。",
  "Change server or password": "更换服务器或密码",
  "Check the connection": "检查连接",
  "Connect Strava once from openGym in a browser, signed in to your server. Your workouts then go up from the server, whichever device you log them on.": "在浏览器中登录你的服务器，从 openGym 连接一次 Strava 即可。之后训练由服务器上传，无论你在哪台设备上记录。",
  "Connected. Your first backup goes up now.": "已连接。第一次备份正在上传。",
