  "Explosive lift (X)": "爆发式上举（X）",
  "Folder address": "文件夹地址",
  "Get set": "准备",
  "Know from your pocket whether to stay put, go back to the top of the superset or move on.": "手机在口袋里就知道：原地不动、回到超级组开头，还是换下一个。",
  "Last backup {0}": "上次备份 {0}",
