  "Leave empty to keep the one saved": "留空则保留已保存的",
  "Like 3-1-1-0: three seconds down, one at the bottom, one up.": "比如 3-1-1-0：下放三秒，底部一秒，上举一秒。",
  "Like the exercise ({0})": "跟随动作（{0}）",
  "Link copied. Paste it into your calendar app.": "链接已复制。粘贴到你的日历应用里。",
  "Make a new link": "生成新链接",
