  "No tempo": "无节奏",
  "Open in my calendar app": "在我的日历应用中打开",
  "Pick one. You choose whether it replaces what is here or merges with it.": "选一个。替换这里的内容还是合并，由你决定。",
  "Reconnect": "重新连接",
  "Rep {0} of {1}": "第 {0} 次，共 {1} 次",
  "Restore from a backup": "从备份恢复",
  "Same as the rest ({0})": "与其余相同（{0}）",
  "Seconds for each part of a rep: lower, pause, lift, squeeze. 3-1-1-0 is three down, one at the bottom, one up, straight into the next.": "一次动作每个部分的秒数：下放、停顿、上举、顶峰收缩。3-1-1-0 就是下放三秒、底部一秒、上举一秒，紧接下一次。",
  "Show finished workouts too": "也显示已完成的训练",
  "Strava connected. Your next workout goes up by itself.": "Strava 已连接。下次训练会自动上传。",
  "Strava disconnected": "Strava 已断开",
  "Strava is listening": "Strava 已就位",
  "Strava is off on this server. Register a Strava API app, then add strava to INTEGRATIONS and its STRAVA_CLIENT_ID and STRAVA_CLIENT_SECRET to the .env, and restart.": "此服务器未开启 Strava。先注册一个 Strava API 应用，然后把 strava 加到 INTEGRATIONS，把 STRAVA_CLIENT_ID 和 STRAVA_CLIENT_SECRET 加到 .env，再重启。",
  "Strava uploads come from your own openGym server, so they need one. Connect this device to it in Account.": "Strava 上传来自你自己的 openGym 服务器，所以需要一台。在“账号”里把这台设备连上它。",
  "Strength workouts too": "力量训练也上传",
  "Subscribe to this link in your calendar app. Anyone with it sees your plan, so keep it to yourself.": "在日历应用里订阅这个链接。拿到它的人都能看到你的计划，所以别外传。",
  "Tempo": "节奏",
  "Tempo for this set": "本组节奏",
  "Tempo {0}": "节奏 {0}",
  "Tempo {0}, start the guide": "节奏 {0}，开始引导",
  "The calendar link is served by your own openGym server, so it needs one. Connect this device to it in Account.": "日历链接由你自己的 openGym 服务器提供，所以需要一台。在“账号”里把这台设备连上它。",
  "The link stops working at once. What your calendar already shows may stay until it refreshes.": "链接会立即失效。日历里已显示的内容可能会保留到下次刷新。",
  "The old link stops working, and every calendar that uses it needs the new one.": "旧链接会失效，所有用它的日历都需要换成新链接。",
  "The password stays on this device, in its secure storage. It is never synced or put in a backup.": "密码只保存在这台设备的安全存储里。永远不会同步，也不会进入备份。",
  "The server cannot show this link again. Make a new one.": "服务器无法再次显示这个链接。生成一个新的吧。",
  "This device stops backing up and forgets the password. The backups already in the folder stay there.": "这台设备将停止备份并忘记密码。文件夹里已有的备份会保留。",
  "Tick the set": "勾选这一组",
  "Turn off": "关闭",
  "Turn off the calendar feed?": "关闭日历订阅？",
  "Up as fast as you can. The guide gives it one quick second.": "尽可能快地上举。引导只给它短短一秒。",
  "Uploading": "正在上传",
  "User name": "用户名",
  "WebDAV backup": "WebDAV 备份",
  "When the app is open, at most once a day, on this device.": "应用打开时，在这台设备上每天最多一次。",
  "Your planned sessions in Apple Calendar, Google Calendar or Outlook, kept up to date. A private link only your calendar knows.": "你计划的训练会出现在 Apple Calendar、Google Calendar 或 Outlook 中，并保持最新。一个只有你的日历知道的私密链接。",
  "Your server forgets the sign-in and stops uploading. What is on Strava stays, and the Strava app keeps its access until you remove it on strava.com.": "你的服务器会忘记登录并停止上传。Strava 上已有的内容会保留，Strava 应用在你到 strava.com 移除之前仍有访问权限。",
  "{0} s per rep, a guide in the workout counts it for you.": "每次 {0} 秒，训练中的引导会帮你数。",
  "{0} s under tension": "受力 {0} 秒",
  "{0} s under tension. Lovely and slow.": "受力 {0} 秒。慢得漂亮。",
  "Backups & calendar": "备份与日历",
  "A copy every day in your own Nextcloud or any WebDAV folder.": "每天一份副本，存到你自己的 Nextcloud 或任意 WebDAV 文件夹。",
  "The full backup, once a day while the app is open, and whenever you tap Back up now.": "完整备份，应用打开时每天一次，每次点“立即备份”时也会备份。",
  "Restore it on a new phone in two taps.": "在新手机上点两下就能恢复。",
  "Your planned sessions in Apple, Google or Outlook calendar.": "你计划的训练出现在 Apple、Google 或 Outlook 日历中。",
  "Planned sessions from a week back to eight weeks ahead, as all-day events.": "从一周前到八周后的计划训练，以全天事件显示。",
  "Finished workouts too, if you like.": "愿意的话，已完成的训练也可以。",
  "Your runs, rides and rows go up to Strava, strength too if you like.": "跑步、骑行和划船会上传到 Strava，愿意的话力量训练也行。",
  "Finished cardio workouts, with their time and distance.": "已完成的有氧训练，带时间和距离。",
  "Strength sessions as Weight Training, if you switch it on.": "开启后，力量训练以重量训练上传。",
  "After a warm-up set": "热身组之后",
  "The ramp is still going.": "热身还没结束。",
  "Between working sets": "正式组之间",
  "Same exercise, next set.": "同一动作，下一组。",
  "Between superset rounds": "超级组轮次之间",
  "Back to the top of the superset.": "回到超级组开头。",
  "Before the next exercise": "下一个动作之前",
  "Time to move on.": "该换下一个了。",
  "Lower": "下放",
  "Lift": "上举",
  "Squeeze": "收缩",
  "Lower (s)": "下放（秒）",
