  "Lift (s)": "上举（秒）",
  "Squeeze at the top (s)": "顶峰收缩（秒）",
  "The server did not take that name and password. An app password usually works best.": "服务器不接受这个用户名和密码。通常用应用专用密码最稳。",
  "That folder is not there, and openGym could not make it. Make it on the server first.": "该文件夹不存在，openGym 也没能创建它。请先在服务器上创建。",
  "The server says this account may not write there.": "服务器说这个账号无权写入那里。",
  "The server is out of space for this account.": "这个账号在服务器上的空间已满。",
  "Could not reach the server. In a browser it also has to allow this site (CORS), see the guide.": "无法连接服务器。在浏览器中，服务器还需要允许本站（CORS），见指南。",
  "Type the password again: this device does not have it.": "请再输入一次密码：这台设备上没有保存。",
