  "Strava has to be allowed to upload activities. Connect again and leave that box ticked.": "必须允许 Strava 上传活动。请重新连接，并保持那个框勾选。",
  "That sign-in took too long or came from somewhere else. Start again from here.": "登录太久了，或者来自别处。请从这里重新开始。",
  "Sign in to your server first, then connect Strava.": "先登录你的服务器，再连接 Strava。",
  "Strava is off on this server.": "此服务器未开启 Strava。",
  "Strava could not be connected. Try again.": "无法连接 Strava。再试一次。",
  "Keeps the newest {0} backup, one per day.": "保留最新的 {0} 份备份，每天一份。",
  "Keeps the newest {0} backups, one per day.": "保留最新的 {0} 份备份，每天一份。",
  // --- promises-146: progression rules, shoulder heads and lats, bench, own media ---,
  "Steady double progression": "稳步双重进阶",
  "Undulating days": "波动训练日",
  "Shorter rests": "更短的休息",
  "Work up a rep range one rep at a time. Every set has to hit the target before it moves, and at the top of the range the weight goes up.": "在次数区间里一次加一次。每组都达到目标后目标才往上走，到了区间顶端就加重量。",
  "Each session rotates: a medium day at your reps, a heavy day with fewer, a light day with more. The weights come from your estimated max, so they climb as you get stronger.": "每次训练轮换：中等日用你的次数，重日次数更少，轻日次数更多。重量来自你的预估最大值，所以会随着你变强而上升。",
  "Same weight, a bit less rest each time every set is clean. At your shortest rest the weight goes up and the rest starts over.": "重量不变，每次所有组都完成干净时休息稍微缩短。到最短休息时加重量，休息重新开始。",
  "Every set hit {0}. Same weight, {1} reps this time.": "每组都完成了 {0} 次。重量不变，这次 {1} 次。",
  "Not every set reached {0} yet. Same weight and target again ({1} of {2} to go).": "还不是每组都达到 {0} 次。重量和目标不变再来一次（还剩 {1}/{2}）。",
  "Every set clean. Same weight with {0}s less rest: {1}s.": "所有组都干净。重量不变，休息少 {0} 秒：{1} 秒。",
  "Clean at your shortest rest. {0} {1} less help, rest back to {2}s.": "在最短休息下完成干净。辅助减少 {0} {1}，休息回到 {2} 秒。",
  "Clean at your shortest rest. {0} {1} more, rest back to {2}s.": "在最短休息下完成干净。加 {0} {1}，休息回到 {2} 秒。",
  "Stuck for {0} sessions. Same weight with more rest: {1}s.": "已经卡住 {0} 次训练。重量不变，多休息：{1} 秒。",
  "Missed reps last time. Same weight and rest again ({0} of {1} to go).": "上次少做了次数。重量和休息不变再来一次（还剩 {0}/{1}）。",
  "Heavy day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "重日：{1} {2} 做 {0} 次，基于你预估的最大值 {3} {2}。",
  "Light day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "轻日：{1} {2} 做 {0} 次，基于你预估的最大值 {3} {2}。",
  "Medium day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "中等日：{1} {2} 做 {0} 次，基于你预估的最大值 {3} {2}。",
